 private void showProxySettings(){
  android.content.SharedPreferences preferences=MusicProxy.prefs(this);
  LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(dp(18),0,dp(18),0);
  TextView note=text("订阅链接需先导入代理客户端并连接。这里填写客户端提供的 HTTP/SOCKS 本地代理地址和端口；如果客户端已启用手机 VPN 模式，保持“跟随手机网络”即可。该设置用于 YouTube 搜索、音频和 MV 播放。",13,muted);form.addView(note);
  Spinner mode=new Spinner(this);String[] modes={"跟随手机网络","HTTP 代理","SOCKS 代理"};ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,modes);mode.setAdapter(adapter);mode.setSelection(!MusicProxy.enabled(this)?0:"socks".equals(MusicProxy.scheme(this))?2:1);form.addView(mode);
  EditText host=new EditText(this);host.setSingleLine(true);host.setHint("代理服务器地址，例如 192.168.1.10");host.setText(MusicProxy.host(this));form.addView(host);
  EditText port=new EditText(this);port.setSingleLine(true);port.setInputType(2);port.setHint("端口，例如 7890");if(MusicProxy.port(this)>0)port.setText(String.valueOf(MusicProxy.port(this)));form.addView(port);
  TextView hint=text("若代理客户端运行在本手机，可填 127.0.0.1。若运行在电脑上，请填电脑的局域网 IP，并在代理客户端开启“允许局域网连接”。不要在此粘贴订阅链接。",12,muted);form.addView(hint);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("YouTube 网络代理").setView(form).setPositiveButton("保存",null).setNegativeButton("取消",null).create();
  dialog.setOnShowListener(ignored->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{int selected=mode.getSelectedItemPosition();String address=host.getText().toString().trim();int number=0;try{number=Integer.parseInt(port.getText().toString().trim());}catch(Exception ignoredNumber){}if(selected!=0&&(address.isEmpty()||number<1||number>65535||address.contains("://")||address.contains("/"))){host.setError("请填写代理主机名或 IP 和有效端口");return;}preferences.edit().putBoolean("enabled",selected!=0).putString("scheme",selected==2?"socks":"http").putString("host",address).putInt("port",number).apply();Toast.makeText(this,selected==0?"已跟随手机网络":"代理已保存；请重开 MV 验证播放",Toast.LENGTH_LONG).show();dialog.dismiss();}));
  dialog.show();
 }
 private void showProxySubscription(){
  LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(dp(18),0,dp(18),0);
  form.addView(text("支持把 Clash 配置或 Trojan 节点订阅交给已安装的代理客户端。客户端连接后，在 MusicBox 的 YouTube 网络代理中选择“跟随手机网络”（VPN 模式），或填写客户端提供的本地代理端口。订阅 URL 本身不能直接作为代理地址。",13,muted));
  EditText link=new EditText(this);link.setSingleLine(false);link.setMinLines(2);link.setHint("粘贴 HTTPS 订阅链接（仅本次使用，不保存在 MusicBox）");form.addView(link);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("导入代理订阅").setView(form).setPositiveButton("发送给代理客户端",null).setNeutralButton("复制链接",null).setNegativeButton("取消",null).create();
  dialog.setOnShowListener(ignored->{
   dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String value=link.getText().toString().trim();if(!validSubscription(value)){link.setError("请输入 HTTPS 订阅链接");return;}Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/plain");send.putExtra(Intent.EXTRA_TEXT,value);startActivity(Intent.createChooser(send,"选择代理客户端"));dialog.dismiss();});
   dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->{String value=link.getText().toString().trim();if(!validSubscription(value)){link.setError("请输入 HTTPS 订阅链接");return;}((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("代理订阅",value));Toast.makeText(this,"已复制，请在代理客户端导入订阅",Toast.LENGTH_LONG).show();dialog.dismiss();});
  });dialog.show();
 }
 private boolean validSubscription(String value){try{URL url=new URL(value);return "https".equalsIgnoreCase(url.getProtocol())&&!url.getHost().isEmpty();}catch(Exception ignored){return false;}}
