  LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(dp(18),dp(8),dp(18),0);
  TextView info=text("优先搜索你自己的百度和夸克网盘。百度扫码登录可搜索个人文件；网页版音频下载可能被百度拒绝。开放平台 Access Token 用于官方播放接口。夸克请输入自己的网盘 Cookie。留空会保留原配置。",13,muted);form.addView(info);
  EditText baidu=new EditText(this);baidu.setSingleLine(true);baidu.setHint(preferences.getString("baidu_token","").isEmpty()?"百度开放平台 Access Token（可选）":"百度 Token 已配置 · 输入新值可更换");baidu.setInputType(129);form.addView(baidu);
  EditText quark=new EditText(this);quark.setSingleLine(true);quark.setHint(preferences.getString("quark_cookie","").isEmpty()?"夸克网盘 Cookie（可选）":"夸克 Cookie 已配置 · 输入新值可更换");quark.setInputType(129);form.addView(quark);
  new AlertDialog.Builder(this).setTitle("个人网盘接入").setView(form).setPositiveButton("保存",(dialog,which)->{android.content.SharedPreferences.Editor edit=preferences.edit();String token=baidu.getText().toString().trim(),cookie=quark.getText().toString().trim();if(!token.isEmpty())edit.putString("baidu_token",token);if(!cookie.isEmpty())edit.putString("quark_cookie",cookie);edit.apply();Toast.makeText(this,"个人网盘配置已保存",Toast.LENGTH_SHORT).show();}).setNeutralButton("清除凭据",(dialog,which)->preferences.edit().clear().apply()).setNegativeButton("取消",null).show();
