 private void playSearchResult(MusicSourceBridge.Song song){playlistQueue.clear();playingPlaylist="";play(song);}
 private void playFromPlaylist(String name,List<MusicSourceBridge.Song> entries,int index){if(entries.isEmpty()||index<0||index>=entries.size())return;playlistQueue.clear();playlistQueue.addAll(entries);playingPlaylist=name;if(nowDialog!=null)nowDialog.dismiss();play(entries.get(index));}
 private List<MusicSourceBridge.Song> activeQueue(){if(!playlistQueue.isEmpty())return new ArrayList<>(playlistQueue);List<MusicSourceBridge.Song> queue=new ArrayList<>();for(MusicSourceBridge.Song song:songs)if(currentResult==null||song.mv==currentResult.mv)queue.add(song);return queue;}
 private void playRelative(int direction){if(currentResult==null)return;List<MusicSourceBridge.Song> queue=activeQueue();int start=queue.indexOf(currentResult);if(start<0||queue.size()<2)return;for(int step=1;step<queue.size();step++){MusicSourceBridge.Song next=queue.get((start+direction*step+queue.size()*2)%queue.size());if(next.mv==currentResult.mv){if(nowDialog!=null)nowDialog.dismiss();play(next);return;}}}
 private void playNext(MusicSourceBridge.Song song){
  if(currentResult==null){playSearchResult(song);return;}
  if(song==currentResult){Toast.makeText(this,"这首正在播放",Toast.LENGTH_SHORT).show();return;}
  if(song.mv!=currentResult.mv){Toast.makeText(this,"请在同一分类中选择下一首",Toast.LENGTH_SHORT).show();return;}
  if(playlistQueue.isEmpty()){playlistQueue.addAll(activeQueue());playingPlaylist="下一首播放";}
  if(!playlistQueue.contains(currentResult))playlistQueue.add(0,currentResult);
  playlistQueue.remove(song);
  int current=playlistQueue.indexOf(currentResult);
  playlistQueue.add(Math.max(0,current+1),song);
  Toast.makeText(this,"已加入下一首："+song.title,Toast.LENGTH_SHORT).show();
 }
 private void toggleRepeat(Button control){repeatOne=!repeatOne;if(player!=null)player.setLooping(repeatOne);if(youtubeAudio!=null)youtubeAudio.setRepeat(repeatOne);if(cloudAudio!=null)cloudAudio.setRepeat(repeatOne);control.setText(repeatOne?"↻¹":"↻");control.setTextColor(repeatOne?green:muted);}
 private void showQueue(){List<MusicSourceBridge.Song> queue=activeQueue();if(queue.isEmpty()){Toast.makeText(this,"当前没有可播放的歌曲",Toast.LENGTH_SHORT).show();return;}int count=Math.min(80,queue.size());String[] labels=new String[count];for(int i=0;i<count;i++)labels[i]=queue.get(i).title+" · "+queue.get(i).source.getName();boolean playlist=!playlistQueue.isEmpty();new AlertDialog.Builder(this).setTitle(playlist?"当前歌单 · "+playingPlaylist:"本次搜索结果 · 临时播放队列").setItems(labels,(dialog,which)->{if(nowDialog!=null)nowDialog.dismiss();if(playlist)play(queue.get(which));else playSearchResult(queue.get(which));}).setNeutralButton("我的歌单",(dialog,which)->showLibrary()).setNegativeButton("关闭",null).show();}
