 private void refreshDaily(){dailyGeneration++;dailyDate="";dailyLoading=false;if(currentPage!=2)renderHome();}
 private void ensureDaily(){
  String today=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.CHINA).format(new Date());
  if(dailyLoading||today.equals(dailyDate))return;
  dailyDate=today;dailyLoading=true;dailyError="";dailySongs.clear();int request=++dailyGeneration;
  recommendationWorker.execute(()->{
   List<DailyRecommendations.Song> found=Collections.emptyList();String error="";boolean personalized=false;
   try{DailyRecommendations.Result response=DailyRecommendations.load(this);found=response.songs;personalized=response.personalized;if(found.isEmpty())error="暂时没有推荐歌曲";}
   catch(Exception unavailable){error="推荐源暂时不可用";}
   List<DailyRecommendations.Song> result=found;String message=error;boolean fromAccount=personalized;
   runOnUiThread(()->{if(destroyed||request!=dailyGeneration||!today.equals(dailyDate))return;dailyLoading=false;dailySongs.clear();dailySongs.addAll(result);dailyError=message;dailyPersonalized=fromAccount;if(currentPage!=2)renderHome();});
  });
 }
