 private void showAddToPlaylist(MusicSourceBridge.Song song){
  List<String> names=MusicLibrary.playlistNames(this);names.add("＋ 新建歌单");
  new AlertDialog.Builder(this).setTitle("加入歌单 · "+song.title).setItems(names.toArray(new String[0]),(dialog,which)->{
   if(which==names.size()-1){promptCreatePlaylist(song);return;}
   if(MusicLibrary.add(this,names.get(which),song))Toast.makeText(this,"已加入："+names.get(which),Toast.LENGTH_SHORT).show();
  }).setNegativeButton("取消",null).show();
 }
 private void showPlaylist(String name){
  List<MusicSourceBridge.Song> entries=MusicLibrary.songs(this,name);
  AlertDialog.Builder builder=new AlertDialog.Builder(this).setTitle(name).setNegativeButton("关闭",null);if(!entries.isEmpty())builder.setPositiveButton("播放全部",(dialog,which)->playFromPlaylist(name,entries,0));
  if(entries.isEmpty())builder.setMessage("这里还没有歌曲。搜索后点歌曲右侧的♡，或长按歌曲加入歌单。");
  else{
   String[] labels=new String[entries.size()];for(int i=0;i<entries.size();i++)labels[i]=entries.get(i).title+" · "+entries.get(i).artist;
   builder.setItems(labels,(dialog,index)->{
    MusicSourceBridge.Song song=entries.get(index);
    new AlertDialog.Builder(this).setTitle(song.title).setItems(new String[]{"从这里播放","从歌单移除","加入其他歌单"},(action,choice)->{
     if(choice==0)playFromPlaylist(name,entries,index);else if(choice==1){MusicLibrary.remove(this,name,song);showPlaylist(name);}else showAddToPlaylist(song);
    }).show();
   });
  }
  if(MusicLibrary.FAVORITES.equals(name))builder.setNeutralButton("新建歌单",(dialog,which)->promptCreatePlaylist(null));
  else builder.setNeutralButton("删除歌单",(dialog,which)->new AlertDialog.Builder(this).setTitle("删除歌单？")
   .setMessage("将删除「"+name+"」及其中的歌曲记录，不会删除网盘里的文件。")
   .setPositiveButton("删除",(confirm,choice)->{MusicLibrary.deletePlaylist(this,name);if(currentPage==0)renderHome();})
   .setNegativeButton("取消",null).show());
  builder.show();
 }
