 private void saveResults(){if(query==null)return;JSONArray data=new JSONArray();for(int i=0;i<songs.size()&&i<500;i++){MusicSourceBridge.Song song=songs.get(i);JSONObject item=new JSONObject();try{item.put("source",song.source.getKey());item.put("id",song.id);item.put("title",song.title);item.put("artist",song.artist);item.put("flag",song.playFlag);item.put("playId",song.playId);item.put("mv",song.mv);item.put("cover",song.cover);data.put(item);}catch(Exception ignored){}}getSharedPreferences("musicbox",0).edit().putInt("result_schema",4).putString("last_query",query.getText().toString()).putString("last_results",data.toString()).apply();}
