 private static String normalized(String value){return value==null?"":value.toLowerCase(Locale.ROOT).replaceAll("[^\\p{L}\\p{N}]","");}
 private int sortRank(MusicSourceBridge.Song song){int match=MusicSourceBridge.relevance(song,activeKeyword);return (PersonalCloud.owns(song)?-1000:0)+match*10+MusicSourceBridge.priority(song.source);}
 private String brief(Throwable t){Throwable c=t;while(c.getCause()!=null)c=c.getCause();return c.getClass().getSimpleName()+(c.getMessage()==null?"":"："+c.getMessage());}
 private static final class SearchBatch {
  final SourceBean site;final List<MusicSourceBridge.Song> songs;final String error;
  SearchBatch(SourceBean s,List<MusicSourceBridge.Song> rows,String e){site=s;songs=rows;error=e;}
 }
 private int sourceScore(SourceBean site){android.content.SharedPreferences p=getSharedPreferences("musicbox_source_stats",0);String key=site.getKey();int ok=p.getInt(key+"_ok",0),fail=p.getInt(key+"_fail",0);return MusicSourceBridge.priority(site)*4-Math.max(-12,Math.min(12,ok*2-fail*3));}
 private List<SourceBean> orderedSites(){List<SourceBean> sites=MusicSourceBridge.musicSites();sites.sort((a,b)->Integer.compare(sourceScore(a),sourceScore(b)));return sites;}
 private boolean isMiaoBo(SourceBean site){String name=site.getName()==null?"":site.getName();String key=site.getKey()==null?"":site.getKey();return name.contains("秒播")||key.toLowerCase(Locale.ROOT).contains("miaobo");}
 private void recordSource(SourceBean site,boolean found,boolean failed){if(!found&&!failed)return;android.content.SharedPreferences p=getSharedPreferences("musicbox_source_stats",0);String key=site.getKey();int ok=p.getInt(key+"_ok",0),fail=p.getInt(key+"_fail",0);if(ok+fail>=20){ok/=2;fail/=2;}if(found)ok++;if(failed)fail++;p.edit().putInt(key+"_ok",ok).putInt(key+"_fail",fail).apply();}
 private List<MusicSourceBridge.Song> searchSiteWithVariants(SourceBean site,String keyword,boolean fast,boolean expand)throws Exception{
  List<MusicSourceBridge.Song> found=new ArrayList<>(MusicSourceBridge.searchVerified(site,keyword,fast));
  String alternate=MusicSearchMatcher.alternate(keyword);
  if(expand&&!alternate.isEmpty()&&found.size()<3&&!Thread.currentThread().isInterrupted()){
   Set<String> seen=new HashSet<>();for(MusicSourceBridge.Song song:found)seen.add(song.id);
   for(MusicSourceBridge.Song song:MusicSourceBridge.searchVerified(site,alternate,fast))if(seen.add(song.id))found.add(song);
   found.sort((a,b)->Integer.compare(MusicSourceBridge.relevance(a,keyword),MusicSourceBridge.relevance(b,keyword)));
  }
  return found;
 }
 private List<MusicSourceBridge.Song> searchPersonalWithVariants(String keyword,PersonalCloud.ResultListener listener)throws Exception{
  List<MusicSourceBridge.Song> found=PersonalCloud.search(this,keyword,listener);
  String alternate=MusicSearchMatcher.alternate(keyword);
  if(found.isEmpty()&&!alternate.isEmpty()&&!Thread.currentThread().isInterrupted())
   found=PersonalCloud.search(this,alternate,listener);
  return found;
 }
 private void search(){suggestionGeneration++;if(suggestionTask!=null)suggestionTask.cancel(true);hideSuggestions();search(false);} private void search(boolean deep){String keyword=query.getText().toString().trim();if(keyword.isEmpty())return;showPage(2);int token=++generation;if(searchTask!=null)searchTask.cancel(true);if(youtubeSearchTask!=null)youtubeSearchTask.cancel(true);activeKeyword=keyword;saveHistory(keyword);busy=true;songs.clear();songRows.clear();items.removeAllViews();status.setOnClickListener(null);status.setText("先搜索我的网盘…");((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);if(YouTubeMv.configured(this))youtubeSearchTask=searchWorker.submit(()->{try{List<MusicSourceBridge.Song> videos=YouTubeMv.search(this,keyword);runOnUiThread(()->{if(destroyed||token!=generation)return;for(MusicSourceBridge.Song video:videos){addSong(video);addSong(YouTubeMv.audioResult(video));}YouTubeMv.prefetchVisible(this,songs);refreshCategory();if(category==1&&!videos.isEmpty())status.setText("YouTube 新增 "+videos.size()+" 个 MV · 订阅源继续搜索中…");});}catch(Exception error){runOnUiThread(()->{if(!destroyed&&token==generation&&category==1)status.setText("YouTube MV 搜索失败 · 请检查网络或代理");});}});
  searchTask=searchWorker.submit(()->{final String[] personalError={""};boolean personalFound=false;try{List<MusicSourceBridge.Song> personal=searchPersonalWithVariants(keyword,batch->runOnUiThread(()->{if(destroyed||token!=generation)return;for(MusicSourceBridge.Song song:batch)addSong(song);refreshCategory();status.setText(songs.size()+" 首来自我的网盘 · 继续搜索中…");}));if(!personal.isEmpty()){personalFound=true;String personalWarning=PersonalCloud.warning();runOnUiThread(()->{if(destroyed||token!=generation)return;status.setText(personal.size()+" 首来自我的网盘 · 正在搜索秒播 MV"+(personalWarning.isEmpty()?"":" · "+personalWarning));});}}catch(Exception error){personalError[0]=brief(error);runOnUiThread(()->{if(!destroyed&&token==generation)status.setText("个人网盘暂不可用，继续搜索其他来源…");});}if(token!=generation||Thread.currentThread().isInterrupted())return;List<SourceBean> sites=orderedSites();if(personalFound)sites.removeIf(site->!isMiaoBo(site));String sourceOnly=com.github.tvbox.osc.BuildConfig.DEBUG?getIntent().getStringExtra("sourceOnly"):null;if(sourceOnly!=null)sites.removeIf(site->!site.getKey().equals(sourceOnly));List<String> errors=new ArrayList<>();if(!personalError[0].isEmpty())errors.add("个人网盘："+personalError[0]);Set<String> seen=new HashSet<>();ExecutorService pool=Executors.newFixedThreadPool(6);CompletionService<SearchBatch> completion=new ExecutorCompletionService<>(pool);List<Future<SearchBatch>> pending=new ArrayList<>();for(SourceBean site:sites)pending.add(completion.submit(()->{try{return new SearchBatch(site,searchSiteWithVariants(site,keyword,!deep,sites.indexOf(site)<8),null);}catch(Throwable error){return new SearchBatch(site,Collections.emptyList(),brief(error));}}));int done=0;long end=System.currentTimeMillis()+(deep?120000:50000);try{while(done<sites.size()&&token==generation){long remaining=end-System.currentTimeMillis();if(remaining<=0)break;Future<SearchBatch> future=completion.poll(Math.min(remaining,1000),TimeUnit.MILLISECONDS);if(future==null)continue;SearchBatch batch=future.get();if(token!=generation||Thread.currentThread().isInterrupted())break;done++;recordSource(batch.site,!batch.songs.isEmpty(),batch.error!=null);if(batch.error!=null)errors.add(batch.site.getName()+"："+batch.error);List<MusicSourceBridge.Song> unique=new ArrayList<>();for(MusicSourceBridge.Song song:batch.songs){if(song.mv&&!isMiaoBo(batch.site))continue;if(personalFound&&!song.mv)continue;String key=song.source.getKey()+":"+song.id+":"+song.playId;if(seen.add(key))unique.add(song);}int count=done;runOnUiThread(()->{if(!destroyed&&token==generation){for(MusicSourceBridge.Song song:unique)addSong(song);refreshCategory();status.setText("正在搜索 "+count+"/"+sites.size()+" 个来源…");}});}}catch(Exception error){errors.add(brief(error));}finally{for(Future<SearchBatch> future:pending)if(!future.isDone())future.cancel(true);pool.shutdownNow();}if(done<sites.size())errors.add((sites.size()-done)+" 个来源超时");runOnUiThread(()->{if(destroyed||token!=generation)return;busy=false;refreshCategory();status.setText(songs.size()+" 个结果 · "+(deep?"深度搜索完成":"点击搜索更多"));status.setOnClickListener(v->{if(!deep)new AlertDialog.Builder(this).setTitle("搜索已完成").setItems(new String[]{"搜索更多（较慢）","查看来源状态"},(dialog,which)->{if(which==0)search(true);else showSourceErrors(errors);}).show();else showSourceErrors(errors);});});});}
