 private boolean hasAudioPlayer(){return player!=null||youtubeAudio!=null||cloudAudio!=null;}
 private boolean isAudioPlaying(){return youtubeAudio!=null?youtubeAudio.isPlaying():cloudAudio!=null?cloudAudio.isPlaying():player!=null&&player.isPlaying();}
